from datetime import datetime

class EmailClient:
    def __init__(self, addr, capacity) -> None:
        self.addr = addr
        self.capacity = capacity
        self.inbox = []

    def send_to(self, recv, content, size):
        if not self._can_receive_email(recv, size):
            self._clear_inbox_for_size(size)
            return False
        self._append_email_to_inbox(recv, content, size)
        return True

    def _can_receive_email(self, recv, size):
        return not recv.is_full_with_one_more_email(size)

    def _append_email_to_inbox(self, recv, content, size):
        email = self._create_email(recv, content, size)
        recv.inbox.append(email)

    def _create_email(self, recv, content, size):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        return {
            "sender": self.addr,
            "receiver": recv.addr,
            "content": content,
            "size": size,
            "time": timestamp,
            "state": "unread"
        }

    def fetch(self):
        if not self.inbox:
            return None
        for email in self.inbox:
            if email['state'] == "unread":
                email['state'] = "read"
                return email
        return None

    def is_full_with_one_more_email(self, size):
        return self.get_occupied_size() + size > self.capacity

    def get_occupied_size(self):
        return sum(email["size"] for email in self.inbox)

    def _clear_inbox_for_size(self, size):
        if len(self.addr) == 0:
            return
        freed_space = 0
        while freed_space < size and self.inbox:
            email = self.inbox[0]
            freed_space += email['size']
            del self.inbox[0]
